function globeProjection(t){return d3.geoOrthographic().rotate([105+(paused?0:Math.sin(t*.000035)*9),-22,0]).translate([W*(W<800?.78:.76),H*.49]).scale(Math.min(W*.30,H*.36)).clipAngle(90)}
const canadaNames=['Canada'];function path(feature,projection,fill,stroke,width=.7){ctx.beginPath();d3.geoPath(projection,ctx)(feature);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
function mapProjection(target){const educ=target==='education';return d3.geoConicConformal().parallels([49,77]).rotate([educ?109:102,0]).center([0,educ?58:47]).translate([W*(W<800?.80:.76),H*(educ?.50:.53)]).scale(Math.min(W,H)*(educ?1.13:.66))}
function drawGlobe(t,opacity=1,zoom=1){ctx.save();ctx.globalAlpha=opacity;const proj=globeProjection(t).scale(Math.min(W*.30,H*.36)*zoom);const center=proj.translate(),r=proj.scale();const halo=ctx.createRadialGradient(...center,r*.8,...center,r*1.16);halo.addColorStop(0,'#4c9cbf00');halo.addColorStop(.83,'#73d5e42a');halo.addColorStop(1,'#73d5e400');ctx.fillStyle=halo;ctx.fillRect(0,0,W,H);path({type:'Sphere'},proj,'#0b2337','#64b7c34f',1);path(d3.geoGraticule10(),proj,'#00000000','#73adbe18',.6);for(const f of countries.features){const ca=f.properties.name==='Canada';path(f,proj,ca?'#7cdbc28c':'#39607572',ca?'#a5f7df99':'#78a4b14d',.65)}ctx.restore()}
function drawMap(target,opacity,zoom=1){ctx.save();ctx.globalAlpha=opacity;const proj=mapProjection(target);proj.scale(proj.scale()*zoom);for(const f of countries.features){const n=f.properties.name;path(f,proj,n==='Canada'?'#1b465cbb':'#18304799',n==='Canada'?'#95d5d08c':'#7496ac4d',.8)}if(target==='education'){for(const f of provinces.features){const bc=f.properties.name==='British Columbia';path(f,proj,bc?'#60d1ad80':'#19425366',bc?'#c5ffe9cc':'#80b7bd40',bc?1.5:.7)}label(proj,[-99,66],'C A N A D A','#94bfd0',16);label(proj,[-126,56],'BRITISH COLUMBIA','#b5f5df',10);pin(proj,[-123.1207,49.2827],'Vancouver',0);pin(proj,[-123.3656,48.4284],'Victoria',1)}else{label(proj,[-110,62],'C A N A D A','#9bc4d5',14);label(proj,[-102,37],'U N I T E D  S T A T E S','#7898ac',11);label(proj,[-102,23],'M E X I C O','#7898ac',10);pin(proj,[-123.12,49.28],'Vancouver / Burnaby',0)}ctx.restore()}
function label(proj,coord,text,color,size){const q=proj(coord);ctx.font=`${size}px Inter,Arial`;ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText(text,...q)}function pin(proj,coord,text,n){const q=proj(coord);ctx.beginPath();ctx.arc(q[0],q[1],4,0,Math.PI*2);ctx.fillStyle='#b9ffe4';ctx.fill();ctx.beginPath();ctx.arc(q[0],q[1],9,0,Math.PI*2);ctx.strokeStyle='#a8f9dc66';ctx.stroke();const dx=25,dy=n?28:-18;ctx.beginPath();ctx.moveTo(...q);ctx.lineTo(q[0]+dx,q[1]+dy);ctx.strokeStyle='#a8f9dc99';ctx.stroke();ctx.textAlign='left';ctx.font='11px Inter,Arial';ctx.fillText(text,q[0]+dx+5,q[1]+dy+4)}
